-    return failure();
-  auto *source = std::get_if<SymbolicOffsetInfo>(&*sourceInfo);
-  if (!source)
-    return Result{};
-  SymbolicArithmetic math(value);
-  auto info = castOffset(*source, value.getType(),
-                         isa<arith::ExtUIOp, arith::IndexCastUIOp>(op), math);
