-      cast<RankedTensorType>(cast<PointerType>(op.getType()).getPointeeType());
-  auto offsets = zeroOffset(tensor.clone(math.builder.getI64Type()), math);
-  for (auto [i, stride] : llvm::enumerate(op.getStrides()))
