-    auto scaled = arithmetic.multiply(
-        coefficient,
-        arithmetic.builder.getIntegerAttr(arithmetic.type, sub.shape));
-    if (failed(scaled))
-      return failure();
-    coefficient = *scaled;
-  }
-  std::reverse(parts.begin(), parts.end());
-  return parts;
