+    EXPECT_EQ(reused->offsets.scalarOffset, origin);
+    unsigned casts = 0;
+    module->walk([&](arith::IndexCastOp op) { casts += op.getIn() == scale; });
+    EXPECT_EQ(casts, 1u);
+    EXPECT_TRUE(succeeded(verify(*module)));
