+void expectAffineLanes(const OffsetInfo &info, ArrayRef<int64_t> expected,
+                       const test::Environment &env = test::Environment()) {
+  ASSERT_TRUE(info.hasStructuredForm());
+  ASSERT_EQ(info.axes.size(), 1u);
